static func _notify() -> void:
	var gs := state()
	gs.movement.clamp_capacity() # wisselen vult nooit energie bij
	gs.equipment_changed.emit()
	gs.progression_changed.emit()


static func equip(item_id: String) -> bool:
	var gs := state()
	var slot := slot_of(item_id)
