## Zwaarden. `reach` is hoe ver je raakt, `damage` hoeveel schade per klap.
const BASE_WEAPONS := {
	"wood": {"name": "Houten zwaard", "item": "sword_wood", "damage": 1, "reach": 34.0, "color": Color(0.85, 0.7, 0.45)},
