func _process(delta: float) -> void:
	t += delta
	if player == null:
		player = Util.player(self)
	queue_redraw()

func interact() -> void:
	Sound.play("select", -6.0)
	if board == "scores":
		GameState.say(tr("Scorebord"), scoreboard_lines())
	else:
		GameState.say(tr("Trofeeënplank"), shelf_lines())


## De tekst van het scorebord, vertaald (ook handig om te testen).

func scoreboard_lines() -> Array:
	# Vertalers: %s is je arena-titel, zoals "Arenastrijder" of "nieuwkomer"
	var lines: Array = [tr("Beste tijden in de arena. Jouw titel: %s.") % Arena.title()]
	for rank: String in Arena.ORDER:
		lines.append("%s: %s" % [tr(Arena.RANKS[rank]["name"]), Arena.record_text(rank)])
	return lines

func shelf_lines() -> Array:
	var lines: Array = [tr("De trofeeënplank van de arena.")]
	var owned := 0
	for item_id: String in SLOTS:
		if GameState.count(item_id) > 0:
			owned += 1
			# Vertalers: achter een trofee op de plank: "Bronzen trofee: gewonnen!"
			var note := tr("een verzamelstuk voor kampioenen.") if item_id == Arena.HELM else tr("gewonnen!")
			lines.append("%s: %s" % [tr(Arena.ITEMS[item_id]["name"]), note])
	if owned == 0:
		lines.append(tr("Nog niets op de plank. Win een rang en zet hier je eerste trofee neer!"))
	elif owned < SLOTS.size():
		lines.append(tr("Er is nog plek op de plank. Win meer rangen!"))
	else:
		lines.append(tr("Een volle plank! Jij bent een echte kampioen."))
	return lines

func _draw() -> void:
	if board == "scores":
		_draw_scores()
	else:
		_draw_shelf()
	if player and player.target == self:
		DrawUtil.prompt(self, Vector2(0, -REACH - 50.0), t)

func _draw_shelf() -> void:
	var width := span * TILE
	var left := -width / 2.0
	var plank := -8.0 # bovenkant van de plank, vlak boven de vloer
	var wood := Color(0.54, 0.35, 0.17)
	var wood_light := Color(0.69, 0.46, 0.22)
	var wood_dark := Color(0.29, 0.18, 0.09)
	# De plank met steuntjes.
	draw_rect(Rect2(left + 2, plank, width - 4, 7), wood_dark)
	draw_rect(Rect2(left + 2, plank, width - 4, 5), wood)
	draw_rect(Rect2(left + 2, plank, width - 4, 1), wood_light)
	for i in span + 1:
		draw_rect(Rect2(left + i * TILE - 2, plank + 6, 4, 5), wood_dark)
	for i in SLOTS.size():
		var center := Vector2(left + (i + 0.5) * TILE, plank - 16.0)
		var owned := GameState.count(SLOTS[i]) > 0
		if owned:
			var sparkle := 0.5 + 0.5 * sin(t * 2.5 + float(i))
			if i == 2 or i == 3:
				draw_circle(center, 14.0 + sparkle * 2.0, Color(1.0, 0.9, 0.4, 0.12 + sparkle * 0.08))
		var tint := Color.WHITE if owned else Color(0.12, 0.1, 0.2, 0.55)
		DrawUtil.sprite(self, Art.tex(Arena.SHEET), i, 0, center, Vector2i(16, 16), 2.0, tint)

