func _ready():
	var points: Array={"river_mouth":[[9,8],[13,23],[8,31],[54,11],[63,26],[51,32]],"harbor":[[9,9],[20,25],[26,7],[62,9],[62,28]],"headland":[[14,15],[22,23],[28,12],[39,16],[46,30],[52,27]]}.get(GameState.map_id,[])
