func setup(cells: Rect2i) -> void:
	footprint = cells
	position = (Vector2(cells.position) + Vector2(cells.size) * 0.5) * TILE

func _process(delta: float) -> void:
	water_strength = move_toward(water_strength,1.0 if preload("res://scripts/core/opening.gd").flowing() else 0.15,delta*0.5)
	clock = fmod(clock + maxf(delta, 0.0), 12.0)
	var next_frame := int(clock * 12.0)
	if next_frame != animation_frame:
		animation_frame = next_frame
		queue_redraw()

static func make_burst(pos: Vector2, tint: Color, amount: int) -> Node2D:
	var fx: Node2D = load("res://scripts/entities/fx.gd").new()
	fx.kind = "burst"
	fx.color = tint
	fx.life = 0.6
	fx.position = pos
	for i in amount:
		var angle := randf() * TAU
		var speed := randf_range(30.0, 110.0)
		fx.particles.append({
			"pos": Vector2.ZERO, "vel": Vector2.from_angle(angle) * speed,
			"size": randf_range(1.5, 3.5),
		})
	return fx

func _process(delta: float) -> void:
	t += delta
	if player == null:
		player = Util.player(self)
	_refresh(false)
	queue_redraw()

func _refresh(first: bool) -> void:
	var now := GameState.check_all(block_if) if not block_if.is_empty() else true
	if now == blocked and not first:
		return
	if not first and not now and blocked:
		Sound.play("door")
	blocked = now
	shape.set_deferred("disabled", not blocked)
	if blocked: # dicht: je kunt hem aanspreken (een sleutel gebruiken, of horen waarom hij dicht is)
		add_to_group("interactable")
	else:
		remove_from_group("interactable")

func interact() -> void:
	if key_item != "" and GameState.count(key_item) > 0:
		GameState.take(key_item)
		GameState.set_flag("gate_" + gate_id)
		GameState.toast.emit(tr("Je opent het poortje met de sleutel."))
	else:
		Sound.play("error", -3.0)
		GameState.toast.emit(tr(locked_text) if locked_text != "" else tr("De poort zit op slot."))

func _draw() -> void:
	if not blocked:
		return
	for y in size_tiles.y:
		for x in size_tiles.x:
			DrawUtil.sprite(self, Art.tex("gate"), 0, 0, Vector2(x * 32.0, y * 32.0), Vector2i(16, 16), 2.0)
	if player and player.target == self:
		DrawUtil.prompt(self, Vector2(float(size_tiles.x - 1) * 16.0, -26.0), t)

