extends StaticBody2D
## Een lessenaar met een open boek in de bibliotheek. E om te lezen. De teksten staan in scripts/data/ext/meer_boeken.gd.
## In de kaart: {"type": "meer_lessenaar", "pos": [x, y], "id": "wachter"}.

const DrawUtil := preload("res://scripts/core/draw_util.gd")
const Art := preload("res://scripts/core/art.gd")
const Util := preload("res://scripts/core/util.gd")
const Boeken := preload("res://scripts/data/ext/meer_boeken.gd")
const Logic := preload("res://scripts/data/ext/meer_logic.gd")

var world: Node
var obj: Dictionary = {}
var key := ""
var book_id := ""
var t := randf() * 4.0
var player: Node2D


func _ready() -> void:
	add_to_group("interactable")
	collision_layer = 1
	book_id = obj.get("id", "")
	var shape := CollisionShape2D.new()
	var rect := RectangleShape2D.new()
	rect.size = Vector2(22, 10)
	shape.shape = rect
	shape.position = Vector2(0, 8)
	add_child(shape)


func _process(delta: float) -> void:
	t += delta
	if player == null:
		player = Util.player(self)
	queue_redraw()


func is_read() -> bool:
	return GameState.flag(Boeken.flag_name(book_id))


func interact() -> void:
	var text: Dictionary = Boeken.TEXTS[book_id]
	var first_time := not is_read()
	GameState.set_flag(Boeken.flag_name(book_id))
	Sound.play("meer_blad", -4.0)
	var lines: Array = text["lines"]
	GameState.say(tr(text["title"]), lines.map(func(line: String) -> String: return tr(line)))
	if first_time and Logic.read_count() == Boeken.TEXTS.size():
		GameState.toast.emit(tr("Je hebt alle boeken in de bibliotheek gelezen!"))


func _draw() -> void:
	DrawUtil.ellipse(self, Vector2(0, 14), Vector2(10, 3), Color(0, 0, 0, 0.25))
	# Een boek dat je nog niet gelezen hebt, glinstert af en toe.
	var glint := not is_read() and fmod(t, 2.4) < 0.5
	DrawUtil.sprite(self, Art.tex("meer_objects"), 1 if glint else 0, 0)
	if player and player.target == self:
		DrawUtil.prompt(self, Vector2(0, -24.0), t)

functions.source:
func _ready() -> void:
	add_to_group("interactable")
	deep = obj.get("type", "") == "meer_diepe_visplek"

func _process(delta: float) -> void:
	t += delta
	hint_wait -= delta
	if player == null:
		player = Util.player(self)
	queue_redraw()

func interact() -> void:
	if GameState.count("fishing_rod") <= 0:
		Sound.play("error", -3.0)
		if hint_wait <= 0.0: # vaak op E drukken stapelt geen rij met dezelfde melding op
			hint_wait = HINT_COOLDOWN
			GameState.toast.emit(tr("Je hebt een hengel nodig. Misschien heeft Visser Joris er een."))
		return
	var ui: Node = world.get_node_or_null("Vissen")
	if ui == null:
		var script: Script = load(UI_SCRIPT)
		ui = script.new()
		ui.name = "Vissen"
		world.add_child(ui)
	ui.call("start", self)

func _draw() -> void:
	# Twee kringetjes die uitdijen en vervagen, een beetje platgedrukt zoals water in perspectief.
	var color := DEEP_RIPPLE_COLOR if deep else RIPPLE_COLOR
	draw_set_transform(Vector2.ZERO, 0.0, Vector2(1.0, 0.55))
	for i in 2:
		var phase := fmod(t * 0.7 + i * 0.5, 1.0)
		draw_arc(Vector2.ZERO, 3.0 + phase * 13.0, 0.0, TAU, 24, Color(color, (1.0 - phase) * 0.7), 2.0)
	draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)
	if deep:
		# Hier en daar een gouden glinstering: de Gouden Karper zwemt hier ergens.
		var glint := sin(t * 1.7) * sin(t * 0.9 + 1.0)
		if glint > 0.55:
			var size := (glint - 0.55) * 14.0
			draw_rect(Rect2(Vector2(5, -6) - Vector2(1, size) / 2.0, Vector2(2, size)), GOLD_GLINT)
			draw_rect(Rect2(Vector2(5, -6) - Vector2(size, 1) / 2.0, Vector2(size, 2)), GOLD_GLINT)
	if player and player.target == self and not GameState.input_locked():
		DrawUtil.name_tag(self, Vector2(0, -22.0), tr("Diepe visplek") if deep else tr("Visplek"))
		DrawUtil.prompt(self, Vector2(0, -36.0), t)

