			for at in [Vector2(5.5,15.5),Vector2(5.5,4.5),Vector2(23.5,4.5)]:
				DrawUtil.ellipse(self,at*32,Vector2(30,22),Color(0.82,0.7,0.43,0.18))

func entrance(at: Vector2, style: int) -> void:
