		glow.texture=Art.light_texture()
		glow.texture_scale=0.28
		glow.color=Color("8cd9da")
		glow.energy=0.12 if kind=="memorial" else 0.25
		add_child(glow)

func _process(delta: float) -> void:
	time+=delta
	pulse=maxf(0,pulse-delta)
