	if not flooded:
		var t:=Time.get_ticks_msec()/1000.0
		for x in range(20,32):
			draw_line(Vector2(x*32+4,26*32+18),Vector2(x*32+22,26*32+18+sin(t+x)*2),Color("b6b29a"),1.5)

