	var tint := Color(0.55, 0.85, 1.8) if cold else Color.WHITE
	DrawUtil.sprite(self, Art.tex("torch"), int(t * 7.0) % 2, 0, Vector2.ZERO, Vector2i(16, 16), 2.0, tint)

