extends Control
## Het einde: de baas valt, de Blauwe Kaart wordt hersteld, een epiloog, je statistieken en de aftiteling.

const Art := preload("res://scripts/core/art.gd")
const UiStyle := preload("res://scripts/core/ui_style.gd")
const DrawUtil := preload("res://scripts/core/draw_util.gd")
const Maps := preload("res://scripts/maps/registry.gd")
const Tiles := preload("res://scripts/data/tiles.gd")
const Items := preload("res://scripts/data/items.gd")
const Quests := preload("res://scripts/data/quests.gd")
const Credits := preload("res://scripts/data/credits.gd")
const MenuUi := preload("res://scripts/ui/menu_ui.gd")
const AchievementBanner := preload("res://scripts/ui/achievement_banner.gd")

const W := 1152.0
const H := 648.0
const SCALE := 4 # pixels per tegel op de kaart

# Waar elk gebied op de kaart komt (in pixels, linksboven).
const ISLANDS := {
	"temple": Vector2(150, 110), "village": Vector2(130, 240), "forest": Vector2(350, 200),
	"ruins": Vector2(610, 100), "cave": Vector2(620, 290),
}
const CRYSTAL_SPOTS := [Vector2(440, 120), Vector2(790, 70), Vector2(790, 250)]

var pages: Array[Dictionary] = []
var page := -1
var t := 0.0
var typed := 0.0
var map_color_tex: Texture2D
var map_gray_tex: Texture2D
var map_origin := Vector2(60, 40)
var credits_scroll := 0.0
var lit := [false, false, false]
var finished := false


func _ready() -> void:
	set_anchors_preset(Control.PRESET_FULL_RECT)
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	GameState.in_game = false
	GameState.ui_owners = {}
	get_tree().paused = false
	_build_map_textures()
	add_child(AchievementBanner.new()) # prestaties van het einde (de Slijmkoning, uitgespeeld...) zie je hier
	# De epiloog, meteen vertaald (de taal kan op dit scherm niet meer veranderen).
	pages = [
		{"type": "text", "speaker": "", "lines": [
			tr("Met een enorme plof zakt de Slijmkoning in elkaar."),
			tr("Het groene gel trekt weg uit de tempel, sijpelt als een rivier door het land... en verdwijnt."),
			tr("Het wordt heel stil in de Kristaltempel."),
		]},
		{"type": "map"},
		{"type": "text", "speaker": tr("Oudste Bram"), "lines": [tr("Dankzij jou is Azura weer veilig. De Blauwe Kaart laat weer zien waar het land rustig is.")]},
		{"type": "text", "speaker": tr("Greta"), "lines": [tr("Ik smeed vanaf nu zwaarden voor op het feest. Nou ja, voor het snijden van de taart.")]},
		{"type": "text", "speaker": tr("Tobias"), "lines": [tr("Mijn winkel draait beter dan ooit! De eerste helddrank van de week is voor jou. Gratis. Ehm... bijna gratis.")]},
		{"type": "text", "speaker": tr("Mila"), "lines": [tr("De herberg zit vol. Iedereen wil de held van Dageraadsdorp zien.")]},
		{"type": "text", "speaker": tr("Pim"), "lines": [tr("Muis en ik gaan ook slijmen verslaan. Als ze groter worden dan Muis, rennen we weg.")]},
		{"type": "stats"},
		{"type": "credits"},
		{"type": "end"},
	]
	Sound.play_music("ending")
	_next_page()


func _build_map_textures() -> void:
	var size := Vector2i(int(W - 120.0), int(H - 100.0))
	var color_img := Image.create_empty(size.x, size.y, false, Image.FORMAT_RGBA8)
	var gray_img := Image.create_empty(size.x, size.y, false, Image.FORMAT_RGBA8)
	for map_id: String in ISLANDS:
		var rows: Array = Maps.get_map(map_id)["rows"]
		var origin: Vector2 = ISLANDS[map_id]
		for y in rows.size():
			var row: String = rows[y]
			for x in row.length():
				var color := Tiles.map_color(Tiles.name_for(row[x], x, y))
				var rect := Rect2i(int(origin.x) + x * SCALE, int(origin.y) + y * SCALE, SCALE, SCALE)
				color_img.fill_rect(rect, color)
				var gray := color.get_luminance() * 0.55
				gray_img.fill_rect(rect, Color(gray, gray, gray * 1.1))
	map_color_tex = ImageTexture.create_from_image(color_img)
	map_gray_tex = ImageTexture.create_from_image(gray_img)


func _next_page() -> void:
	page += 1
	t = 0.0
	typed = 0.0
	if pages[page]["type"] == "text":
		pages[page]["line"] = 0
	if pages[page]["type"] == "credits":
		credits_scroll = 0.0


func _unhandled_input(event: InputEvent) -> void:
	if not Controls.allows_event(event):
		return
	if event.is_echo():
		return
	if event.is_action_pressed("pause") or event.is_action_pressed("ui_cancel"):
		get_viewport().set_input_as_handled()
		_to_title()
		return
	if not (event.is_action_pressed("interact") or event.is_action_pressed("attack") or event.is_action_pressed("ui_accept")):
		return
	get_viewport().set_input_as_handled()
	var current := pages[page]
	match current["type"]:
		"text":
			var line: String = current["lines"][current["line"]]
			if typed < line.length():
				typed = line.length()
			elif current["line"] < current["lines"].size() - 1:
				current["line"] += 1
				typed = 0.0
				Sound.play("select", -8.0)
			else:
				_next_page()
		"map":
			if t > 9.0:
				_next_page()
			else:
				t = maxf(t, 9.0)
		"stats":
			if t > 1.0:
				_next_page()
		"credits":
			credits_scroll += 400.0
		"end":
			_to_title()


func _to_title() -> void:
	if finished:
		return
	finished = true
	get_tree().change_scene_to_file("res://scenes/title.tscn")


func _process(delta: float) -> void:
	t += delta
	var current := pages[page]
	match current["type"]:
		"text":
			typed += delta * 40.0
		"map":
			var times := [0.8, 2.6, 4.4]
			for i in 3:
				if not lit[i] and t > times[i]:
					lit[i] = true
					Sound.play("crystal", -2.0)
			if t > 6.2 and t - delta <= 6.2:
				Sound.play("upgrade", -2.0)
		"credits":
			credits_scroll += delta * 55.0
			if credits_scroll > Credits.LINES.size() * 40.0 + H:
				_next_page()
	queue_redraw()


# --- Tekenen ------------------------------------------------------------------------------------

func _draw() -> void:
	# Keep the original composition together at small and large window sizes.
	draw_rect(Rect2(Vector2.ZERO, size), Color(0.03, 0.05, 0.14))
	var factor := minf(size.x / W, size.y / H)
	draw_set_transform((size - Vector2(W, H) * factor) * 0.5, 0.0, Vector2.ONE * factor)
	draw_polygon(PackedVector2Array([Vector2(0, 0), Vector2(W, 0), Vector2(W, H), Vector2(0, H)]),
		PackedColorArray([Color(0.03, 0.05, 0.14), Color(0.03, 0.05, 0.14), Color(0.1, 0.18, 0.38), Color(0.1, 0.18, 0.38)]))
	var rng := RandomNumberGenerator.new()
	rng.seed = 5
	for i in 60:
		var p := Vector2(rng.randf() * W, rng.randf() * H * 0.8)
		var twinkle := 0.3 + 0.7 * absf(sin(t * rng.randf_range(0.8, 2.2) + rng.randf() * TAU))
		draw_rect(Rect2(p, Vector2(3, 3)), Color(1, 1, 1, twinkle))
	var current := pages[page]
	match current["type"]:
		"text":
			_draw_text_page(current)
		"map":
			_draw_map_page()
		"stats":
			_draw_stats()
		"credits":
			_draw_credits()
		"end":
			_draw_end()


func _draw_box(rect: Rect2) -> void:
	draw_style_box(UiStyle.flat(Color(0.05, 0.08, 0.2, 0.9), Color(0.45, 0.75, 1.0), 3), rect)


func _text_centered(text: String, y: float, size: int, color: Color) -> void:
	var font := ThemeDB.fallback_font
	draw_string_outline(font, Vector2(0, y), text, HORIZONTAL_ALIGNMENT_CENTER, W, size, 6, Color(0, 0, 0, 0.8))
	draw_string(font, Vector2(0, y), text, HORIZONTAL_ALIGNMENT_CENTER, W, size, color)


func _draw_text_page(current: Dictionary) -> void:
	var font := ThemeDB.fallback_font
	var line: String = current["lines"][current["line"]]
	var shown := line.substr(0, int(typed))
	var box := Rect2(120, 220, W - 240, 220)
	_draw_box(box)
	if current["speaker"] != "":
		draw_string(font, box.position + Vector2(28, 44), current["speaker"], HORIZONTAL_ALIGNMENT_LEFT, -1, 26, Color(0.55, 0.85, 1.0))
	draw_multiline_string(font, box.position + Vector2(28, 90), shown, HORIZONTAL_ALIGNMENT_LEFT, box.size.x - 56.0, 28, -1, Color.WHITE)
	var hint := Controls.action_label("ui_accept") + "  ▼" if typed >= line.length() else ""
	draw_string(font, box.position + Vector2(box.size.x - 70, box.size.y - 16), hint, HORIZONTAL_ALIGNMENT_LEFT, -1, 18, Color(1, 1, 1, 0.6))


func _draw_map_page() -> void:
	var font := ThemeDB.fallback_font
	var progress := clampf((t - 6.2) / 2.0, 0.0, 1.0)
	var frame := Rect2(map_origin - Vector2(20, 14), Vector2(W - 80, H - 72))
	draw_style_box(UiStyle.flat(Color(0.05, 0.1, 0.26, 0.95), Color(0.9, 0.8, 0.4), 4), frame)
	draw_texture(map_gray_tex, map_origin, Color(1, 1, 1, 1.0 - progress))
	draw_texture(map_color_tex, map_origin, Color(1, 1, 1, progress))
	# naamplaatjes
	var names := {"temple": tr("Kristaltempel"), "village": tr("Dageraadsdorp"), "forest": tr("Fluisterbos"), "ruins": tr("Vergeten Ruïne"), "cave": tr("Echo-grot")}
	for map_id: String in ISLANDS:
		var p: Vector2 = map_origin + ISLANDS[map_id]
		draw_string_outline(font, p + Vector2(0, -6), names[map_id], HORIZONTAL_ALIGNMENT_LEFT, -1, 16, 4, Color(0, 0, 0, 0.8))
		draw_string(font, p + Vector2(0, -6), names[map_id], HORIZONTAL_ALIGNMENT_LEFT, -1, 16, Color(1, 1, 1, 0.5 + progress * 0.5))
	# de drie kristallen
	var items_tex := Art.tex("items")
	var crystal_ids := ["crystal_bos", "crystal_ruine", "crystal_grot"]
	for i in 3:
		var spot: Vector2 = map_origin + CRYSTAL_SPOTS[i] + Vector2(0, sin(t * 2.0 + float(i)) * 4.0)
		var icon: int = Items.ITEMS[crystal_ids[i]]["icon"]
		if lit[i]:
			var since: float = t - float([0.8, 2.6, 4.4][i])
			var glow := 40.0 + sin(t * 4.0) * 6.0 + maxf(0.0, 2.0 - since) * 40.0
			draw_circle(spot, glow, Color(0.4, 0.8, 1.0, 0.16))
			draw_circle(spot, glow * 0.6, Color(0.6, 0.9, 1.0, 0.2))
			draw_line(spot, map_origin + Vector2(480, 220), Color(0.6, 0.9, 1.0, 0.3 * minf(since, 1.0)), 3.0)
		draw_texture_rect_region(items_tex, Rect2(spot - Vector2(32, 32), Vector2(64, 64)), Rect2(Vector2(icon * 16, 0), Vector2(16, 16)),
			Color(1, 1, 1, 1.0 if lit[i] else 0.3))
	if progress > 0.5:
		var alpha := clampf((t - 7.2) / 1.0, 0.0, 1.0)
		_text_centered(tr("De Blauwe Kaart is weer heel."), H - 24.0, 34, Color(0.85, 0.95, 1.0, alpha))


func _draw_stats() -> void:
	var font := ThemeDB.fallback_font
	_text_centered(tr("Jouw avontuur"), 120, 54, Color(0.7, 0.92, 1.0))
	var done := 0
	for quest_id: String in Quests.QUESTS:
		if GameState.quest_state(quest_id) == "done":
			done += 1
	var weapon: Dictionary = Items.WEAPONS[GameState.weapon]
	var rows := [
		[tr("Speeltijd"), MenuUi.format_time(GameState.play_time)],
		[tr("Verslagen vijanden"), str(GameState.kills)],
		[tr("Munten"), str(GameState.coins)],
		[tr("Zwaard"), tr(weapon["name"])],
		[tr("Hartjes"), str(GameState.max_hp())],
		# Vertalers: aantal voltooide opdrachten: "5 van 9"
		[tr("Opdrachten voltooid"), tr("%d van %d") % [done, Quests.QUESTS.size()]],
	]
	var box := Rect2(280, 170, W - 560, 330)
	_draw_box(box)
	for i in rows.size():
		var shown := clampf((t - 0.3 - float(i) * 0.35) * 3.0, 0.0, 1.0)
		var y := box.position.y + 62.0 + i * 46.0
		draw_string(font, Vector2(box.position.x + 30, y), rows[i][0], HORIZONTAL_ALIGNMENT_LEFT, -1, 26, Color(0.8, 0.9, 1.0, shown))
		draw_string(font, Vector2(box.position.x, y), rows[i][1], HORIZONTAL_ALIGNMENT_RIGHT, box.size.x - 30.0, 26, Color(1.0, 0.9, 0.5, shown))
	if t > 3.0:
		draw_string(font, Vector2(box.position.x, box.end.y + 40.0), Controls.action_label("ui_accept") + "  ▼", HORIZONTAL_ALIGNMENT_CENTER, box.size.x, 20, Color(1, 1, 1, 0.6))


func _draw_credits() -> void:
	var y := H - credits_scroll
	for entry: Array in Credits.LINES:
		match entry[0]:
			"title":
				_text_centered(tr(entry[1]), y, 64, Color(0.7, 0.92, 1.0))
			"heading":
				_text_centered(tr(entry[1]), y, 28, Color(1.0, 0.88, 0.5))
			"text":
				_text_centered(tr(entry[1]), y, 24, Color(0.9, 0.95, 1.0))
		y += 40.0


func _draw_end() -> void:
	var pulse := 0.75 + 0.25 * sin(t * 3.0)
	var crystal := Vector2(W / 2.0, 200.0 + sin(t * 2.0) * 8.0)
	draw_circle(crystal, 90.0, Color(0.4, 0.8, 1.0, 0.12))
	DrawUtil.sprite(self, Art.tex("crystal"), int(t * 1.4) % 2, 0, crystal, Vector2i(16, 16), 8.0)
	_text_centered(tr("Bedankt voor het spelen!"), 400, 64, Color(0.7, 0.92, 1.0))
	_text_centered(tr("Je voortgang is bewaard: je kunt verder in het dorp."), 450, 24, Color(0.85, 0.9, 1.0))
	_text_centered(tr("Druk op %s om naar het titelscherm te gaan") % Controls.action_label("ui_accept"), 520, 26, Color(1, 1, 1, pulse))

functions.source:
func slots() -> Array[String]:
	var result: Array[String] = []
	for id: String in Equipment.SLOTS:
		result.append(id)
	result.append_array(["weapon", "boots"])
	return result

func alternatives() -> Array[String]:
	var result: Array[String] = []
	for id: String in Items.ITEMS:
		if Equipment.slot_of(id) == slot_id():
			result.append(id)
	return result

func current_item(slot: String) -> String:
	if slot == "weapon":
		return Items.WEAPONS[GameState.weapon]["item"]
	if slot == "boots":
		return "boots" if GameState.count("boots") > 0 else ""
	return Equipment.equipped(slot)

func candidate() -> String:
	var options := alternatives()
	return "" if options.is_empty() else options[clampi(selected_item, 0, options.size() - 1)]

func select_slot(index: int) -> void:
	selected_slot = clampi(index, 0, slots().size() - 1)
	selected_item = 0
	var options := alternatives()
	var current := current_item(slot_id())
	if current in options:
		selected_item = options.find(current)
	zone = 0
	refresh()

func _fit_detail() -> void:
	if not is_instance_valid(detail): return
	for font_size in range(17,14,-1):
		detail.add_theme_font_size_override("normal_font_size",font_size)
		if detail.get_content_height() <= detail.size.y: break

func navigate(action: String) -> void:
	var down := action in ["ui_down", "ui_right"]
	if zone == 0:
		if action in ["ui_up", "ui_down"]:
			select_slot(selected_slot + (1 if down else -1))
		elif action == "ui_right" and not alternatives().is_empty():
			zone = 1
	elif zone == 1:
		if action == "ui_left":
			zone = 0
		elif action == "ui_right" or (action == "ui_down" and selected_item == alternatives().size() - 1):
			zone = 2
			action_index = 0
		elif action in ["ui_up", "ui_down"]:
			selected_item = clampi(selected_item + (1 if down else -1), 0, alternatives().size() - 1)
	else:
		if action == "ui_up":
			zone = 1
		elif action == "ui_left":
			if action_index == 0:
				zone = 0
			else:
				action_index = 0
		elif action in ["ui_right", "ui_down"]:
			action_index = 1
	refresh()

func confirm() -> void:
	if alternatives().is_empty():
		return
	if zone == 0:
		zone = 1
	elif zone == 1:
		zone = 2 # show the explicit action before committing a choice
		action_index = 0
	else:
		apply_action(action_index)
	queue_redraw()

func apply_action(action: int) -> void:
	var changed := false
	if action == 0 and can_equip():
		changed = Equipment.equip(candidate())
	elif action == 1 and can_remove():
		changed = Equipment.unequip(slot_id())
	if changed:
		Sound.play("select", -4.0)
	refresh()

func _pointer_input(event: InputEvent) -> void:
	if Controls.controller_active or not event is InputEventMouseButton or not event.pressed:
		return
	if event.button_index == MOUSE_BUTTON_RIGHT:
		close_requested.emit()
		accept_event()
		return
	if event.button_index != MOUSE_BUTTON_LEFT:
		return
	if alternatives().size() > 2 and (PREV_RECT.has_point(event.position) or NEXT_RECT.has_point(event.position)):
		selected_item = clampi(selected_item+(-2 if PREV_RECT.has_point(event.position) else 2),0,alternatives().size()-1)
		zone = 1
		refresh(); accept_event(); return
	for index in slots().size():
		if slot_rect(index).has_point(event.position):
			select_slot(index)
			accept_event()
			return
	for index in visible_indices():
		if item_rect(index).has_point(event.position):
			selected_item = index
			zone = 1
			refresh()
			accept_event()
			return
	if EQUIP_RECT.has_point(event.position) or REMOVE_RECT.has_point(event.position):
		zone = 2
		action_index = 0 if EQUIP_RECT.has_point(event.position) else 1
		apply_action(action_index)
		accept_event()

func visible_indices() -> Array[int]:
	var result: Array[int] = []
	var first := (selected_item/2)*2
	for index in range(first,mini(first+2,alternatives().size())): result.append(index)
	return result

func _draw() -> void:
	_text(Vector2(0, 24), tr("Uitrusting kiezen"), 24, GOLD)
	_text(Vector2(0, 48), tr("Vijf verwisselbare plekken; zwaard en laarzen werken automatisch."), 17, BLUE)
	for index in slots().size():
		var id: String = slots()[index]
		var rect := slot_rect(index)
		_box(rect, index == selected_slot, zone == 0 and index == selected_slot)
		var item := current_item(id)
		_icon(item, rect.position + Vector2(8, 8))
		var title := tr("Zwaard") if id == "weapon" else tr("Laarzen") if id == "boots" else tr(Equipment.SLOTS[id]["name"])
		_text(rect.position + Vector2(50, 19), title, 17, BLUE)
		_text(rect.position + Vector2(50, 39), tr("Leeg") if item == "" else tr(Items.info(item)["name"]), 16, Color.WHITE)
	var options := alternatives()
	if options.is_empty():
		_text(Vector2(356, 92), tr("Automatisch actief"), 24, GOLD)
		_text(Vector2(356, 126), tr("Deze plek volgt je bestaande upgrades."), 18, BLUE)
	else:
		if options.size() > 2:
			_box(PREV_RECT,false,false); _box(NEXT_RECT,false,false)
			_text(PREV_RECT.position+Vector2(6,22),"‹",22,BLUE)
			_text(NEXT_RECT.position+Vector2(6,22),"›",22,BLUE)
			draw_string(ThemeDB.fallback_font,Vector2(874,40),"%d/%d" % [selected_item/2+1,ceili(options.size()/2.0)],HORIZONTAL_ALIGNMENT_CENTER,48,15,BLUE)
		for index in visible_indices():
			var item: String = options[index]
			var rect := item_rect(index)
			_box(rect, index == selected_item, zone == 1 and index == selected_item)
			_icon(item, rect.position + Vector2(9, 12))
			_text(rect.position + Vector2(52, 24), tr(Items.info(item)["name"]), 19, Color.WHITE)
			draw_string(ThemeDB.fallback_font,rect.position+Vector2(52,47),Equipment.stats_text(item),HORIZONTAL_ALIGNMENT_LEFT,540,14,BLUE)
			var status := tr("Uitgerust") if Equipment.equipped(slot_id()) == item else tr("In bezit") if GameState.count(item) > 0 else tr("Niet in bezit")
			draw_string(ThemeDB.fallback_font, rect.position + Vector2(416, 24), status, HORIZONTAL_ALIGNMENT_RIGHT, 182, 15, GOLD if GameState.count(item) > 0 else Color(0.65, 0.7, 0.8))
		_draw_action(EQUIP_RECT, tr("%s  Uitrusten") % Controls.action_label("ui_accept"), can_equip(), zone == 2 and action_index == 0)
		_draw_action(REMOVE_RECT, tr("Afdoen"), can_remove(), zone == 2 and action_index == 1)

func _box(rect: Rect2, selected: bool, focused: bool) -> void:
	draw_rect(rect, Color(0.17, 0.27, 0.43) if selected else Color(0.1, 0.16, 0.28))
	if selected:
		draw_rect(rect, GOLD if focused else Color(0.4, 0.6, 0.8), false, 2.0)

func _draw_action(rect: Rect2, label: String, enabled: bool, focused: bool) -> void:
	draw_rect(rect, Color(0.15, 0.33, 0.3) if enabled else Color(0.12, 0.16, 0.22))
	if focused:
		draw_rect(rect, GOLD, false, 2.0)
	draw_string(ThemeDB.fallback_font, rect.position + Vector2(0, 28), label, HORIZONTAL_ALIGNMENT_CENTER, rect.size.x, 20, Color.WHITE if enabled else Color(0.5, 0.58, 0.7))

func _icon(item: String, at: Vector2) -> void:
	if item == "":
		draw_rect(Rect2(at, Vector2(32, 32)), Color(0.25, 0.35, 0.5), false, 1.0)
		return
	var info := Items.info(item)
	draw_texture_rect_region(Art.tex(Items.sheet_of(item)), Rect2(at, Vector2(32, 32)), Rect2(int(info["icon"]) * 16, 0, 16, 16))

func detail_text() -> String:
	if slot_id() == "weapon":
		return tr("Zwaard: %s · schade %d · bereik %d") % [tr(Items.WEAPONS[GameState.weapon]["name"]), GameState.damage(), GameState.reach()] + "\n\n" + tr("Je beste zwaard blijft automatisch actief. Bekijk Voortgang voor Greta's prijzen en de route naar het Sterrenzwaard.")
	if slot_id() == "boots":
		return (tr("Snelle laarzen zijn actief: +%d%% loopsnelheid.") % roundi((GameState.BOOTS_SPEED_MULTIPLIER - 1.0) * 100.0) if GameState.count("boots") > 0 else tr("Koop snelle laarzen bij Tobias. Daarna zijn ze automatisch actief.")) + "\n\n" + tr("Bekijk Voortgang voor prijs en locatie. Deze bestaande upgrade hoef je niet aan of uit te zetten.")
	var current := Equipment.equipped(slot_id())
	var lines: Array[String] = [tr("Nu: %s") % (tr("Geen bonus") if current == "" else Equipment.stats_text(current)), tr("Na wisselen: %s") % Equipment.stats_text(candidate()), Equipment.comparison_text(candidate())]
	lines.append(source_text(candidate()))
	return "\n".join(lines)

func source_text(item: String) -> String:
	for offer: Dictionary in Shops.info("tobias")["items"]:
		if offer["item"] == item:
			return tr("Tobias · dorpswinkel · %d munten (je hebt %d)") % [offer["price"], GameState.coins]
	for id: String in Recipes.RECIPES:
		var recipe: Dictionary = Recipes.RECIPES[id]
		if recipe["output"] != item:
			continue
		var needs: Array[String] = []
		for material: String in recipe["inputs"]:
			needs.append(tr("%s %d/%d") % [tr(Items.info(material)["name"]), GameState.count(material), recipe["inputs"][material]])
		var text := tr("Maken via %s · %s niveau %d · %s") % [Controls.action_label("crafting"), tr(Recipes.SKILLS[recipe["skill"]]["name"]), recipe["level"], tr(Recipes.TEXT[recipe.get("station", "anywhere")])] + "\n" + ", ".join(needs)
		if recipe.has("unlock") and not GameState.flag(recipe.unlock): text += "\n" + tr(recipe.get("unlock_hint","Nog vergrendeld: herstel de prismabank of Mees’ oversteek."))
		return text
	match item:
		"gear_ra_grip": return tr("Beloning: breng de weerkaart terug naar het kamp in de Bergpas.")
		"gear_ra_compass": return tr("Beloning: orden de gebeurtenissen in het Rietarchief.")
		"gear_rf_keepsake": return tr("Beloning: voltooi Wilfreds gedenksteen in de Ruïne.")
		"gear_rf_cord": return tr("Vind de schuilplaats achter de klankschalen in de Echo-grot.")
		"gear_bastion_coat": return tr("Beloning: verdedig de twee vuurkorven in IJsdal.")
	return ""

