extends Control
## Browsing is read-only. Only the explicit equip/remove action changes equipment.

const Equipment := preload("res://scripts/core/equipment.gd")
const Items := preload("res://scripts/data/items.gd")
const Recipes := preload("res://scripts/data/ext/beroepen.gd")
const Shops := preload("res://scripts/data/shops.gd")
const Art := preload("res://scripts/core/art.gd")
const GOLD := Color(1.0, 0.88, 0.4)
const BLUE := Color(0.65, 0.85, 1.0)
const EQUIP_RECT := Rect2(344, 386, 292, 42)
const REMOVE_RECT := Rect2(650, 386, 302, 42)
const PREV_RECT := Rect2(844,18,28,28)
const NEXT_RECT := Rect2(924,18,28,28)

signal close_requested

var selected_slot := 0
var selected_item := 0
var zone := 0 # slots, alternatives, action buttons
var action_index := 0 # equip, remove
var detail: RichTextLabel


func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_PASS
	texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
	detail = RichTextLabel.new()
	detail.position = Vector2(354, 198)
	detail.size = Vector2(588, 178)
	detail.focus_mode = Control.FOCUS_NONE
	detail.scroll_active = false
	detail.add_theme_font_size_override("normal_font_size", 17)
	detail.add_theme_color_override("default_color", Color(0.86, 0.92, 1.0))
	detail.mouse_filter = Control.MOUSE_FILTER_IGNORE
	add_child(detail)
	gui_input.connect(_pointer_input)
	GameState.items_changed.connect(refresh)
	GameState.equipment_changed.connect(refresh)
	Lang.changed.connect(func(_locale: String) -> void: refresh())
	Controls.device_changed.connect(func(_pad: bool) -> void: queue_redraw())
	Controls.bindings_changed.connect(queue_redraw)
	refresh()


func slots() -> Array[String]:
	var result: Array[String] = []
	for id: String in Equipment.SLOTS:
		result.append(id)
	result.append_array(["weapon", "boots"])
	return result


func slot_id() -> String:
	return slots()[selected_slot]


func alternatives() -> Array[String]:
	var result: Array[String] = []
	for id: String in Items.ITEMS:
		if Equipment.slot_of(id) == slot_id():
			result.append(id)
	return result


func current_item(slot: String) -> String:
	if slot == "weapon":
		return Items.WEAPONS[GameState.weapon]["item"]
	if slot == "boots":
		return "boots" if GameState.count("boots") > 0 else ""
	return Equipment.equipped(slot)


func candidate() -> String:
	var options := alternatives()
	return "" if options.is_empty() else options[clampi(selected_item, 0, options.size() - 1)]


func select_slot(index: int) -> void:
	selected_slot = clampi(index, 0, slots().size() - 1)
	selected_item = 0
	var options := alternatives()
	var current := current_item(slot_id())
	if current in options:
		selected_item = options.find(current)
	zone = 0
	refresh()


func refresh() -> void:
	if detail == null:
		return
	selected_item = clampi(selected_item, 0, maxi(alternatives().size() - 1, 0))
	detail.text = detail_text()
	_fit_detail.call_deferred()
	queue_redraw()

func _fit_detail() -> void:
	if not is_instance_valid(detail): return
	for font_size in range(17,14,-1):
		detail.add_theme_font_size_override("normal_font_size",font_size)
		if detail.get_content_height() <= detail.size.y: break


func navigate(action: String) -> void:
	var down := action in ["ui_down", "ui_right"]
	if zone == 0:
		if action in ["ui_up", "ui_down"]:
			select_slot(selected_slot + (1 if down else -1))
		elif action == "ui_right" and not alternatives().is_empty():
			zone = 1
	elif zone == 1:
		if action == "ui_left":
			zone = 0
		elif action == "ui_right" or (action == "ui_down" and selected_item == alternatives().size() - 1):
			zone = 2
			action_index = 0
		elif action in ["ui_up", "ui_down"]:
			selected_item = clampi(selected_item + (1 if down else -1), 0, alternatives().size() - 1)
	else:
		if action == "ui_up":
			zone = 1
		elif action == "ui_left":
			if action_index == 0:
				zone = 0
			else:
				action_index = 0
		elif action in ["ui_right", "ui_down"]:
			action_index = 1
	refresh()


func confirm() -> void:
	if alternatives().is_empty():
		return
	if zone == 0:
		zone = 1
	elif zone == 1:
		zone = 2 # show the explicit action before committing a choice
		action_index = 0
	else:
		apply_action(action_index)
	queue_redraw()


func can_equip() -> bool:
	return candidate() != "" and GameState.count(candidate()) > 0 and Equipment.equipped(slot_id()) != candidate()


func can_remove() -> bool:
	return Equipment.SLOTS.has(slot_id()) and Equipment.equipped(slot_id()) != ""


func apply_action(action: int) -> void:
	var changed := false
	if action == 0 and can_equip():
		changed = Equipment.equip(candidate())
	elif action == 1 and can_remove():
		changed = Equipment.unequip(slot_id())
	if changed:
		Sound.play("select", -4.0)
	refresh()


func _pointer_input(event: InputEvent) -> void:
	if Controls.controller_active or not event is InputEventMouseButton or not event.pressed:
		return
	if event.button_index == MOUSE_BUTTON_RIGHT:
		close_requested.emit()
		accept_event()
		return
	if event.button_index != MOUSE_BUTTON_LEFT:
		return
	if alternatives().size() > 2 and (PREV_RECT.has_point(event.position) or NEXT_RECT.has_point(event.position)):
		selected_item = clampi(selected_item+(-2 if PREV_RECT.has_point(event.position) else 2),0,alternatives().size()-1)
		zone = 1
		refresh(); accept_event(); return
	for index in slots().size():
		if slot_rect(index).has_point(event.position):
			select_slot(index)
			accept_event()
			return
	for index in visible_indices():
		if item_rect(index).has_point(event.position):
			selected_item = index
			zone = 1
			refresh()
			accept_event()
			return
	if EQUIP_RECT.has_point(event.position) or REMOVE_RECT.has_point(event.position):
		zone = 2
		action_index = 0 if EQUIP_RECT.has_point(event.position) else 1
		apply_action(action_index)
		accept_event()


func slot_rect(index: int) -> Rect2:
	return Rect2(0, 62 + index * 52, 326, 48)


func item_rect(index: int) -> Rect2:
	return Rect2(344, 62 + (index-(selected_item/2)*2) * 65, 608, 59)

func visible_indices() -> Array[int]:
	var result: Array[int] = []
	var first := (selected_item/2)*2
	for index in range(first,mini(first+2,alternatives().size())): result.append(index)
	return result


func _draw() -> void:
	_text(Vector2(0, 24), tr("Uitrusting kiezen"), 24, GOLD)
	_text(Vector2(0, 48), tr("Vijf verwisselbare plekken; zwaard en laarzen werken automatisch."), 17, BLUE)
	for index in slots().size():
		var id: String = slots()[index]
		var rect := slot_rect(index)
		_box(rect, index == selected_slot, zone == 0 and index == selected_slot)
		var item := current_item(id)
		_icon(item, rect.position + Vector2(8, 8))
		var title := tr("Zwaard") if id == "weapon" else tr("Laarzen") if id == "boots" else tr(Equipment.SLOTS[id]["name"])
		_text(rect.position + Vector2(50, 19), title, 17, BLUE)
		_text(rect.position + Vector2(50, 39), tr("Leeg") if item == "" else tr(Items.info(item)["name"]), 16, Color.WHITE)
	var options := alternatives()
	if options.is_empty():
		_text(Vector2(356, 92), tr("Automatisch actief"), 24, GOLD)
		_text(Vector2(356, 126), tr("Deze plek volgt je bestaande upgrades."), 18, BLUE)
	else:
		if options.size() > 2:
			_box(PREV_RECT,false,false); _box(NEXT_RECT,false,false)
			_text(PREV_RECT.position+Vector2(6,22),"‹",22,BLUE)
			_text(NEXT_RECT.position+Vector2(6,22),"›",22,BLUE)
			draw_string(ThemeDB.fallback_font,Vector2(874,40),"%d/%d" % [selected_item/2+1,ceili(options.size()/2.0)],HORIZONTAL_ALIGNMENT_CENTER,48,15,BLUE)
		for index in visible_indices():
			var item: String = options[index]
			var rect := item_rect(index)
			_box(rect, index == selected_item, zone == 1 and index == selected_item)
			_icon(item, rect.position + Vector2(9, 12))
			_text(rect.position + Vector2(52, 24), tr(Items.info(item)["name"]), 19, Color.WHITE)
			draw_string(ThemeDB.fallback_font,rect.position+Vector2(52,47),Equipment.stats_text(item),HORIZONTAL_ALIGNMENT_LEFT,540,14,BLUE)
			var status := tr("Uitgerust") if Equipment.equipped(slot_id()) == item else tr("In bezit") if GameState.count(item) > 0 else tr("Niet in bezit")
			draw_string(ThemeDB.fallback_font, rect.position + Vector2(416, 24), status, HORIZONTAL_ALIGNMENT_RIGHT, 182, 15, GOLD if GameState.count(item) > 0 else Color(0.65, 0.7, 0.8))
		_draw_action(EQUIP_RECT, tr("%s  Uitrusten") % Controls.action_label("ui_accept"), can_equip(), zone == 2 and action_index == 0)
		_draw_action(REMOVE_RECT, tr("Afdoen"), can_remove(), zone == 2 and action_index == 1)


func _box(rect: Rect2, selected: bool, focused: bool) -> void:
	draw_rect(rect, Color(0.17, 0.27, 0.43) if selected else Color(0.1, 0.16, 0.28))
	if selected:
		draw_rect(rect, GOLD if focused else Color(0.4, 0.6, 0.8), false, 2.0)


func _draw_action(rect: Rect2, label: String, enabled: bool, focused: bool) -> void:
	draw_rect(rect, Color(0.15, 0.33, 0.3) if enabled else Color(0.12, 0.16, 0.22))
	if focused:
		draw_rect(rect, GOLD, false, 2.0)
	draw_string(ThemeDB.fallback_font, rect.position + Vector2(0, 28), label, HORIZONTAL_ALIGNMENT_CENTER, rect.size.x, 20, Color.WHITE if enabled else Color(0.5, 0.58, 0.7))


func _text(at: Vector2, text: String, size: int, color: Color) -> void:
	draw_string(ThemeDB.fallback_font, at, text, HORIZONTAL_ALIGNMENT_LEFT, -1, size, color)


func _icon(item: String, at: Vector2) -> void:
	if item == "":
		draw_rect(Rect2(at, Vector2(32, 32)), Color(0.25, 0.35, 0.5), false, 1.0)
		return
	var info := Items.info(item)
	draw_texture_rect_region(Art.tex(Items.sheet_of(item)), Rect2(at, Vector2(32, 32)), Rect2(int(info["icon"]) * 16, 0, 16, 16))


func detail_text() -> String:
	if slot_id() == "weapon":
		return tr("Zwaard: %s · schade %d · bereik %d") % [tr(Items.WEAPONS[GameState.weapon]["name"]), GameState.damage(), GameState.reach()] + "\n\n" + tr("Je beste zwaard blijft automatisch actief. Bekijk Voortgang voor Greta's prijzen en de route naar het Sterrenzwaard.")
	if slot_id() == "boots":
		return (tr("Snelle laarzen zijn actief: +%d%% loopsnelheid.") % roundi((GameState.BOOTS_SPEED_MULTIPLIER - 1.0) * 100.0) if GameState.count("boots") > 0 else tr("Koop snelle laarzen bij Tobias. Daarna zijn ze automatisch actief.")) + "\n\n" + tr("Bekijk Voortgang voor prijs en locatie. Deze bestaande upgrade hoef je niet aan of uit te zetten.")
	var current := Equipment.equipped(slot_id())
	var lines: Array[String] = [tr("Nu: %s") % (tr("Geen bonus") if current == "" else Equipment.stats_text(current)), tr("Na wisselen: %s") % Equipment.stats_text(candidate()), Equipment.comparison_text(candidate())]
	lines.append(source_text(candidate()))
	return "\n".join(lines)


func source_text(item: String) -> String:
	for offer: Dictionary in Shops.info("tobias")["items"]:
		if offer["item"] == item:
			return tr("Tobias · dorpswinkel · %d munten (je hebt %d)") % [offer["price"], GameState.coins]
	for id: String in Recipes.RECIPES:
		var recipe: Dictionary = Recipes.RECIPES[id]
		if recipe["output"] != item:
			continue
		var needs: Array[String] = []
		for material: String in recipe["inputs"]:
			needs.append(tr("%s %d/%d") % [tr(Items.info(material)["name"]), GameState.count(material), recipe["inputs"][material]])
		var text := tr("Maken via %s · %s niveau %d · %s") % [Controls.action_label("crafting"), tr(Recipes.SKILLS[recipe["skill"]]["name"]), recipe["level"], tr(Recipes.TEXT[recipe.get("station", "anywhere")])] + "\n" + ", ".join(needs)
		if recipe.has("unlock") and not GameState.flag(recipe.unlock): text += "\n" + tr(recipe.get("unlock_hint","Nog vergrendeld: herstel de prismabank of Mees’ oversteek."))
		return text
	match item:
		"gear_ra_grip": return tr("Beloning: breng de weerkaart terug naar het kamp in de Bergpas.")
		"gear_ra_compass": return tr("Beloning: orden de gebeurtenissen in het Rietarchief.")
		"gear_rf_keepsake": return tr("Beloning: voltooi Wilfreds gedenksteen in de Ruïne.")
		"gear_rf_cord": return tr("Vind de schuilplaats achter de klankschalen in de Echo-grot.")
		"gear_bastion_coat": return tr("Beloning: verdedig de twee vuurkorven in IJsdal.")
	return ""

functions.source:
func _fade(target: float, duration: float) -> void:
	if tween and tween.is_valid():
		tween.kill()
	tween = create_tween().set_pause_mode(Tween.TWEEN_PAUSE_PROCESS)
	tween.tween_property(rect, "color:a", target, duration)
	await tween.finished

func _exit_tree() -> void:
	GameState.set_ui("vissen", false)


## Begint met vissen bij deze visplek.

func _splash(at: Vector2, radius: float, sparks: int) -> void:
	# De wereld staat stil tijdens het vissen, dus deze effecten moeten zelf blijven bewegen.
	for fx: Node2D in [Fx.make_ring(at, radius, Color(1, 1, 1, 0.9)), Fx.make_burst(at, Color(0.8, 0.92, 1.0), sparks)]:
		fx.process_mode = Node.PROCESS_MODE_ALWAYS
		world.fx_layer.add_child(fx)

func _update_reel(delta: float) -> void:
	var holding := Input.is_action_pressed("interact") or Input.is_action_pressed("ui_accept")
	if not Controls.controller_active:
		holding = holding or Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT)
	reel.update(delta, holding)
	haspel_timer -= delta
	if reel.in_zone and haspel_timer <= 0.0:
		haspel_timer = HASPEL_INTERVAL
		Sound.play("meer_haspel", -9.0)
	if reel.state != "bezig":
		_finish(reel.state)

func _unhandled_input(event: InputEvent) -> void:
	if not Controls.allows_event(event):
		return
	if phase == "idle" or Engine.get_process_frames() == opened_frame or event.is_echo():
		return
	if event.is_action_pressed("pause") or event.is_action_pressed("ui_cancel") or (event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_RIGHT):
		get_viewport().set_input_as_handled()
		close()
	elif event.is_action_pressed("interact") or event.is_action_pressed("ui_accept") or (event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT):
		get_viewport().set_input_as_handled()
		if phase == "bite":
			_start_reel()
		elif phase == "result" and phase_time >= RESULT_LOCK:
			_cast()


# --- Tekenen ---------------------------------------------------------------------------------------

func _rod_tip() -> Vector2:
	var player: Node2D = world.player
	return player.global_position + player.facing * 12.0 + Vector2(0, -6)

func _bobber_world() -> Vector2:
	var tip := _rod_tip()
	var target: Vector2 = spot.global_position
	match phase:
		"cast":
			var f := clampf(phase_time / CAST_TIME, 0.0, 1.0)
			return tip.lerp(target, f) + Vector2(0, -sin(f * PI) * 40.0)
		"wait":
			return target + Vector2(0, sin(phase_time * 3.0) * 1.5)
		"bite":
			return target + Vector2(sin(phase_time * 50.0) * 2.0, 3.0)
		"reel":
			# Hoe voller de balk, hoe dichter de dobber bij jou komt.
			return target.lerp(tip, maxf(reel.progress - Reel.START_PROGRESS, 0.0) * 0.8)
	return target

func _draw_line_and_bobber() -> void:
	var tip := _screen(_rod_tip())
	var bobber := _screen(_bobber_world())
	var sag := 12.0 if phase in ["cast", "reel"] else 26.0
	var points := PackedVector2Array()
	for i in 15:
		var f := float(i) / 14.0
		points.append(tip.lerp(bobber, f) + Vector2(0, sin(f * PI) * sag))
	root.draw_polyline(points, LINE_COLOR, 2.0)
	# Kringetjes rond de dobber zodra hij in het water ligt
	if phase in ["wait", "bite", "reel"]:
		root.draw_set_transform(bobber + Vector2(0, 8), 0.0, Vector2(1.0, 0.5))
		for i in 2:
			var ring := fmod(phase_time * 0.8 + i * 0.5, 1.0)
			root.draw_arc(Vector2.ZERO, 10.0 + ring * 34.0, 0.0, TAU, 28, Color(1, 1, 1, (1.0 - ring) * 0.7), 3.0)
		root.draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)
	var dipped := phase == "bite" and int(phase_time * 14.0) % 2 == 1
	root.draw_texture_rect_region(Art.tex("meer_ui"), Rect2(bobber - Vector2(8.0, 10.0) * ART_PIXEL, Vector2(16, 16) * ART_PIXEL),
		Rect2(Vector2(16 if dipped else 0, 0), Vector2(16, 16)))

func _draw_status(line: String, hint: String) -> void:
	var rect := STATUS_PANEL
	_panel(rect)
	_text(Vector2(rect.position.x, rect.position.y + 34), line, 26, Color.WHITE, rect.size.x, HORIZONTAL_ALIGNMENT_CENTER)
	if hint != "":
		_text(Vector2(rect.position.x, rect.position.y + 58), hint, 16, Color(1, 1, 1, 0.6), rect.size.x, HORIZONTAL_ALIGNMENT_CENTER)

func _draw_bite() -> void:
	# Een uitroepteken boven het hoofd van de speler en een balk die leegloopt: nu snel!
	var head := _screen(world.player.global_position) + Vector2(-32, -140 + sin(phase_time * 30.0) * 4.0)
	root.draw_texture_rect_region(Art.tex("meer_ui"), Rect2(head, Vector2(16, 16) * ART_PIXEL), Rect2(Vector2(32, 0), Vector2(16, 16)))
	_draw_status(tr("BEET!  Druk snel op %s!") % Controls.action_label("interact"), "")
	var left := clampf(1.0 - phase_time / BITE_WINDOW, 0.0, 1.0)
	root.draw_rect(Rect2(STATUS_PANEL.position + Vector2(10, STATUS_PANEL.size.y - 14), Vector2((STATUS_PANEL.size.x - 20.0) * left, 8)), Color(1.0, 0.45, 0.35))

func _catch_note() -> String:
	if catch_id == Vis.GOLDEN:
		return tr("Zo zeldzaam! Breng hem naar Visser Joris!")
	var value: int = Logic.price_now(catch_id)
	if catch_id == "meer_laars":
		return tr_n("Joris verzamelt ze. Waarde: %d munt", "Joris verzamelt ze. Waarde: %d munten", value) % value
	return tr_n("Waarde: %d munt", "Waarde: %d munten", value) % value

func _draw_sparkles(card: Rect2) -> void:
	for i in 8:
		var phase_i := fmod(phase_time * 1.3 + i * 0.37, 1.0)
		var angle := float(i) * 0.9 + 0.5
		var centre := Vector2(card.position.x + card.size.x / 2.0, 262.0)
		var at := centre + Vector2.from_angle(angle) * (70.0 + phase_i * 50.0)
		var size := sin(phase_i * PI) * 8.0
		root.draw_rect(Rect2(at - Vector2(size, 2) / 2.0, Vector2(size, 3)), Color(1, 0.95, 0.6))
		root.draw_rect(Rect2(at - Vector2(2, size) / 2.0, Vector2(3, size)), Color(1, 0.95, 0.6))

proceduralSources.source:
extends CanvasLayer
## Het visspel. Wordt gestart door een visplek (scripts/entities/meer_visplek.gd) en zet het spel stil zolang het open is.
##
##   cast   de dobber vliegt het water in
##   wait   wachten op een beet (1 tot 3 seconden, willekeurig)
##   bite   BEET! Druk binnen 0,8 seconde op E, anders ontsnapt de vis
##   reel   binnenhalen: houd de vis in de groene zone (zie fishing_reel.gd)
##   result een kaartje met wat je gevangen hebt (of dat hij ontsnapt is)
##
## Esc of P (of B op een controller) stopt altijd en geeft de besturing terug. E op het kaartje gooit opnieuw uit.
## Rollen (Shift) stopt het visspel niet: zo verlies je je vis niet door een verkeerde toets.
## Voor tests: `forced_catch` bepaalt welke vis bijt, `forced_wait` hoe lang je wacht en `rng.seed` de rest.

const Art := preload("res://scripts/core/art.gd")
const Fx := preload("res://scripts/entities/fx.gd")
const Items := preload("res://scripts/data/items.gd")
const UiStyle := preload("res://scripts/core/ui_style.gd")
const Util := preload("res://scripts/core/util.gd")
const Vis := preload("res://scripts/data/ext/meer_vis.gd")
const Logic := preload("res://scripts/data/ext/meer_logic.gd")
const Reel := preload("res://scripts/ui/fishing_reel.gd")

const CAST_TIME := 0.5
const BITE_WINDOW := 0.8 # zo lang heb je om op E te drukken als de dobber zakt
const RESULT_LOCK := 0.5 # het kaartje blijft even staan, zodat je er niet per ongeluk doorheen klikt
const ART_PIXEL := 4.0 # één pixel van de art is 4 pixels op het scherm (2x vergroot in de wereld, 2x camerazoom)
const HASPEL_INTERVAL := 0.36 # zo vaak klikt de haspel terwijl je binnenhaalt

# Indeling van het scherm (1152x648): rechts het binnenhaal-paneel, onderin de status, in het midden het kaartje.
const REEL_PANEL := Rect2(826, 120, 270, 400)
const BAR := Rect2(872, 190, 64, 280) # de balk waarin de vis en de zone bewegen
const PROGRESS := Rect2(962, 190, 26, 280) # de voortgangsbalk ernaast
const STATUS_PANEL := Rect2(326, 468, 500, 70) # boven de meldingen van de HUD, die onderin verschijnen
const RESULT_CARD := Rect2(346, 150, 460, 300)
const PANEL_COLOR := Color(0.05, 0.08, 0.18, 0.92)
const PANEL_BORDER := Color(0.45, 0.75, 1.0)
const LINE_COLOR := Color(0.92, 0.95, 1.0, 0.9)
const GOLD := Color(1.0, 0.88, 0.35)

var phase := "idle" # idle, cast, wait, bite, reel of result
var outcome := "" # bij result: gevangen, te_laat of ontsnapt
var catch_id := "" # de vis die bijt of die je gevangen hebt
var phase_time := 0.0
var wait_time := 0.0
var reel: RefCounted # fishing_reel.gd, alleen tijdens het binnenhalen
var spot: Node2D
var world: Node
var rng := RandomNumberGenerator.new()
var forced_catch := ""
var forced_wait := -1.0
var opened_frame := -1
var haspel_timer := 0.0
var root: Control


func _ready() -> void:
	layer = 14
	process_mode = Node.PROCESS_MODE_ALWAYS
	rng.randomize()
	root = Control.new()
	root.set_anchors_preset(Control.PRESET_FULL_RECT)
	root.mouse_filter = Control.MOUSE_FILTER_IGNORE
	root.visible = false
	root.draw.connect(_draw_content)
	add_child(root)


func _exit_tree() -> void:
	GameState.set_ui("vissen", false)


## Begint met vissen bij deze visplek.
func start(new_spot: Node2D) -> void:
	if phase != "idle":
		return
	spot = new_spot
	world = Util.world(self)
	var to_spot: Vector2 = spot.global_position - world.player.global_position
	if to_spot.length() > 1.0:
		world.player.facing = to_spot.normalized() # de speler kijkt naar het water
	opened_frame = Engine.get_process_frames()
	root.visible = true
	GameState.set_ui("vissen", true)
	spot.queue_redraw() # de wereld staat nu stil: zonder dit blijft de E-knop van de visplek in beeld
	_cast()


func close() -> void:
	phase = "idle"
	reel = null
	root.visible = false
	GameState.set_ui("vissen", false)
	Sound.play("select", -6.0)


func _cast() -> void:
	phase = "cast"
	phase_time = 0.0
	Sound.play("dodge", -8.0, 1.4)


func _land() -> void:
	phase = "wait"
	phase_time = 0.0
	wait_time = forced_wait if forced_wait >= 0.0 else rng.randf_range(Vis.WAIT_MIN, Vis.WAIT_MAX)
	Sound.play("meer_plons")
	_splash(spot.global_position, 22.0, 8)


func _bite() -> void:
	phase = "bite"
	phase_time = 0.0
	catch_id = forced_catch if forced_catch != "" else Vis.roll(rng, bool(spot.get("deep")), Logic.pity(), Logic.golden_can_bite())
	Sound.play("meer_beet")
	_splash(spot.global_position, 16.0, 4)


func _start_reel() -> void:
	phase = "reel"
	phase_time = 0.0
	haspel_timer = 0.0
	reel = Reel.new(rng, Vis.stats(catch_id))


func _finish(result: String) -> void:
	phase = "result"
	phase_time = 0.0
	outcome = result
	reel = null
	if result == "gevangen":
		GameState.give(catch_id, 1, true)
		Logic.record_catch(catch_id, bool(spot.get("deep")))
		Sound.play("meer_vangst")
		_splash(spot.global_position, 30.0, 14)
		if catch_id == Vis.GOLDEN:
			Sound.play("crystal", -2.0)
			GameState.toast.emit(tr("Je hebt de Gouden Karper gevangen!"))
	else:
		Sound.play("meer_ontsnapt")


func _splash(at: Vector2, radius: float, sparks: int) -> void:
	# De wereld staat stil tijdens het vissen, dus deze effecten moeten zelf blijven bewegen.
	for fx: Node2D in [Fx.make_ring(at, radius, Color(1, 1, 1, 0.9)), Fx.make_burst(at, Color(0.8, 0.92, 1.0), sparks)]:
		fx.process_mode = Node.PROCESS_MODE_ALWAYS
		world.fx_layer.add_child(fx)


func _process(delta: float) -> void:
	if phase == "idle":
		return
	phase_time += delta
	match phase:
		"cast":
			if phase_time >= CAST_TIME:
				_land()
		"wait":
			if phase_time >= wait_time:
				_bite()
		"bite":
			if phase_time >= BITE_WINDOW:
				_finish("te_laat")
		"reel":
			_update_reel(delta)
	root.queue_redraw()


func _update_reel(delta: float) -> void:
	var holding := Input.is_action_pressed("interact") or Input.is_action_pressed("ui_accept")
	if not Controls.controller_active:
		holding = holding or Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT)
	reel.update(delta, holding)
	haspel_timer -= delta
	if reel.in_zone and haspel_timer <= 0.0:
		haspel_timer = HASPEL_INTERVAL
		Sound.play("meer_haspel", -9.0)
	if reel.state != "bezig":
		_finish(reel.state)


func _unhandled_input(event: InputEvent) -> void:
	if not Controls.allows_event(event):
		return
	if phase == "idle" or Engine.get_process_frames() == opened_frame or event.is_echo():
		return
	if event.is_action_pressed("pause") or event.is_action_pressed("ui_cancel") or (event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_RIGHT):
		get_viewport().set_input_as_handled()
		close()
	elif event.is_action_pressed("interact") or event.is_action_pressed("ui_accept") or (event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT):
		get_viewport().set_input_as_handled()
		if phase == "bite":
			_start_reel()
		elif phase == "result" and phase_time >= RESULT_LOCK:
			_cast()


# --- Tekenen ---------------------------------------------------------------------------------------

func _screen(world_pos: Vector2) -> Vector2:
	return root.get_viewport().get_canvas_transform() * world_pos


func _rod_tip() -> Vector2:
	var player: Node2D = world.player
	return player.global_position + player.facing * 12.0 + Vector2(0, -6)


func _bobber_world() -> Vector2:
	var tip := _rod_tip()
	var target: Vector2 = spot.global_position
	match phase:
		"cast":
			var f := clampf(phase_time / CAST_TIME, 0.0, 1.0)
			return tip.lerp(target, f) + Vector2(0, -sin(f * PI) * 40.0)
		"wait":
			return target + Vector2(0, sin(phase_time * 3.0) * 1.5)
		"bite":
			return target + Vector2(sin(phase_time * 50.0) * 2.0, 3.0)
		"reel":
			# Hoe voller de balk, hoe dichter de dobber bij jou komt.
			return target.lerp(tip, maxf(reel.progress - Reel.START_PROGRESS, 0.0) * 0.8)
	return target


func _text(pos: Vector2, text: String, size: int, color := Color.WHITE, width := -1.0, align := HORIZONTAL_ALIGNMENT_LEFT) -> void:
	var font := ThemeDB.fallback_font
	root.draw_string_outline(font, pos, text, align, width, size, 5, Color(0, 0, 0, 0.9))
	root.draw_string(font, pos, text, align, width, size, color)


func _panel(rect: Rect2) -> void:
	root.draw_style_box(UiStyle.flat(PANEL_COLOR, PANEL_BORDER, 3), rect)


func _draw_content() -> void:
	if phase == "idle":
		return
	if phase != "result":
		_draw_line_and_bobber()
	match phase:
		"cast":
			_draw_status(tr("Je gooit uit..."), "")
		"wait":
			_draw_status(tr("Wacht op een beet") + ".".repeat(1 + int(phase_time * 2.0) % 3), tr("%s: stoppen") % Controls.action_label("ui_cancel"))
		"bite":
			_draw_bite()
		"reel":
			_draw_reel()
		"result":
			_draw_result()


func _draw_line_and_bobber() -> void:
	var tip := _screen(_rod_tip())
	var bobber := _screen(_bobber_world())
	var sag := 12.0 if phase in ["cast", "reel"] else 26.0
	var points := PackedVector2Array()
	for i in 15:
		var f := float(i) / 14.0
		points.append(tip.lerp(bobber, f) + Vector2(0, sin(f * PI) * sag))
	root.draw_polyline(points, LINE_COLOR, 2.0)
	# Kringetjes rond de dobber zodra hij in het water ligt
	if phase in ["wait", "bite", "reel"]:
		root.draw_set_transform(bobber + Vector2(0, 8), 0.0, Vector2(1.0, 0.5))
		for i in 2:
			var ring := fmod(phase_time * 0.8 + i * 0.5, 1.0)
			root.draw_arc(Vector2.ZERO, 10.0 + ring * 34.0, 0.0, TAU, 28, Color(1, 1, 1, (1.0 - ring) * 0.7), 3.0)
		root.draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)
	var dipped := phase == "bite" and int(phase_time * 14.0) % 2 == 1
	root.draw_texture_rect_region(Art.tex("meer_ui"), Rect2(bobber - Vector2(8.0, 10.0) * ART_PIXEL, Vector2(16, 16) * ART_PIXEL),
		Rect2(Vector2(16 if dipped else 0, 0), Vector2(16, 16)))


func _draw_status(line: String, hint: String) -> void:
	var rect := STATUS_PANEL
	_panel(rect)
	_text(Vector2(rect.position.x, rect.position.y + 34), line, 26, Color.WHITE, rect.size.x, HORIZONTAL_ALIGNMENT_CENTER)
	if hint != "":
		_text(Vector2(rect.position.x, rect.position.y + 58), hint, 16, Color(1, 1, 1, 0.6), rect.size.x, HORIZONTAL_ALIGNMENT_CENTER)


func _draw_bite() -> void:
	# Een uitroepteken boven het hoofd van de speler en een balk die leegloopt: nu snel!
	var head := _screen(world.player.global_position) + Vector2(-32, -140 + sin(phase_time * 30.0) * 4.0)
	root.draw_texture_rect_region(Art.tex("meer_ui"), Rect2(head, Vector2(16, 16) * ART_PIXEL), Rect2(Vector2(32, 0), Vector2(16, 16)))
	_draw_status(tr("BEET!  Druk snel op %s!") % Controls.action_label("interact"), "")
	var left := clampf(1.0 - phase_time / BITE_WINDOW, 0.0, 1.0)
	root.draw_rect(Rect2(STATUS_PANEL.position + Vector2(10, STATUS_PANEL.size.y - 14), Vector2((STATUS_PANEL.size.x - 20.0) * left, 8)), Color(1.0, 0.45, 0.35))


func _draw_reel() -> void:
	var panel := REEL_PANEL
	_panel(panel)
	_text(Vector2(panel.position.x, 160), tr("Binnenhalen!"), 26, GOLD, panel.size.x, HORIZONTAL_ALIGNMENT_CENTER)
	# De balk met de groene zone en de vis
	root.draw_rect(BAR, Color(0.07, 0.13, 0.3))
	for i in range(1, 10):
		root.draw_line(Vector2(BAR.position.x, BAR.position.y + BAR.size.y * i / 10.0),
			Vector2(BAR.position.x + 10, BAR.position.y + BAR.size.y * i / 10.0), Color(0.3, 0.45, 0.7), 2.0)
	var zone_h: float = reel.zone_size * BAR.size.y
	var zone_y: float = BAR.position.y + BAR.size.y * (1.0 - reel.zone_pos) - zone_h / 2.0
	var zone := Rect2(BAR.position.x + 4, zone_y, BAR.size.x - 8, zone_h)
	root.draw_rect(zone, Color(0.3, 0.9, 0.45, 0.9 if reel.in_zone else 0.6))
	root.draw_rect(zone, Color(0.8, 1.0, 0.85), false, 3.0)
	root.draw_rect(BAR, Color(0.45, 0.75, 1.0), false, 3.0)
	var fish_y: float = BAR.position.y + BAR.size.y * (1.0 - reel.fish_pos)
	var wiggle := sin(phase_time * 14.0) * 2.0
	var icon: int = int(Items.info(catch_id)["icon"])
	root.draw_texture_rect_region(Art.tex(Items.sheet_of(catch_id)), Rect2(BAR.position.x + 16 + wiggle, fish_y - 16, 32, 32),
		Rect2(Vector2(icon * 16, 0), Vector2(16, 16)))
	# De voortgangsbalk: vult zich als de vis in de zone zit
	root.draw_rect(PROGRESS, Color(0.07, 0.13, 0.3))
	var filled: float = PROGRESS.size.y * reel.progress
	var fill_color := Color(0.3, 0.9, 0.45) if reel.in_zone else Color(0.95, 0.55, 0.3)
	root.draw_rect(Rect2(PROGRESS.position.x, PROGRESS.position.y + PROGRESS.size.y - filled, PROGRESS.size.x, filled), fill_color)
	root.draw_rect(PROGRESS, Color(0.45, 0.75, 1.0), false, 3.0)
	_text(Vector2(panel.position.x, 498), tr("Houd %s ingedrukt: omhoog") % Controls.action_label("interact"), 16, Color(1, 1, 1, 0.75), panel.size.x, HORIZONTAL_ALIGNMENT_CENTER)
	_draw_status(tr("Houd de vis in het groen!"), tr("Loslaten: zakken  ·  %s: stoppen") % Controls.action_label("ui_cancel"))


func _draw_result() -> void:
	var card := RESULT_CARD
	_panel(card)
	var info := Items.info(catch_id)
	match outcome:
		"gevangen":
			_text(Vector2(card.position.x, 196), tr("Gevangen!"), 34, GOLD, card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
			var icon: int = int(info["icon"])
			var bob := sin(phase_time * 5.0) * 4.0
			root.draw_texture_rect_region(Art.tex(Items.sheet_of(catch_id)), Rect2(card.position.x + card.size.x / 2.0 - 48, 214 + bob, 96, 96),
				Rect2(Vector2(icon * 16, 0), Vector2(16, 16)))
			_text(Vector2(card.position.x, 346), tr(info["name"]), 28, Color.WHITE, card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
			_text(Vector2(card.position.x, 378), _catch_note(), 18, Color(0.85, 0.93, 1.0), card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
			if catch_id == Vis.GOLDEN:
				_draw_sparkles(card)
		"te_laat":
			_text(Vector2(card.position.x, 250), tr("Te laat!"), 34, Color(1.0, 0.55, 0.45), card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
			_text(Vector2(card.position.x, 296), tr("De vis is ontsnapt."), 22, Color.WHITE, card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
			_text(Vector2(card.position.x, 330), tr("Druk op %s zodra de dobber zakt.") % Controls.action_label("interact"), 18, Color(0.85, 0.93, 1.0), card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
		_:
			_text(Vector2(card.position.x, 250), tr("Hij is ontsnapt!"), 34, Color(1.0, 0.55, 0.45), card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
			_text(Vector2(card.position.x, 296), tr("De lijn werd te slap."), 22, Color.WHITE, card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
			_text(Vector2(card.position.x, 330), tr("Houd de vis in de groene zone."), 18, Color(0.85, 0.93, 1.0), card.size.x, HORIZONTAL_ALIGNMENT_CENTER)
	_text(Vector2(card.position.x, 428), tr("%s: nog een keer  ·  %s: stoppen") % [Controls.action_label("interact"), Controls.action_label("ui_cancel")], 18, Color(1, 1, 1, 0.65), card.size.x, HORIZONTAL_ALIGNMENT_CENTER)


## Een zinnetje bij de vangst, met wat hij nu oplevert (minder als het dorp vol vis zit, meer met de pet).
func _catch_note() -> String:
	if catch_id == Vis.GOLDEN:
		return tr("Zo zeldzaam! Breng hem naar Visser Joris!")
	var value: int = Logic.price_now(catch_id)
	if catch_id == "meer_laars":
		return tr_n("Joris verzamelt ze. Waarde: %d munt", "Joris verzamelt ze. Waarde: %d munten", value) % value
	return tr_n("Waarde: %d munt", "Waarde: %d munten", value) % value


func _draw_sparkles(card: Rect2) -> void:
	for i in 8:
		var phase_i := fmod(phase_time * 1.3 + i * 0.37, 1.0)
		var angle := float(i) * 0.9 + 0.5
		var centre := Vector2(card.position.x + card.size.x / 2.0, 262.0)
		var at := centre + Vector2.from_angle(angle) * (70.0 + phase_i * 50.0)
		var size := sin(phase_i * PI) * 8.0
		root.draw_rect(Rect2(at - Vector2(size, 2) / 2.0, Vector2(size, 3)), Color(1, 0.95, 0.6))
		root.draw_rect(Rect2(at - Vector2(2, size) / 2.0, Vector2(3, size)), Color(1, 0.95, 0.6))

functions.source:
static func shortcut() -> String:
 var controls: Node=(Engine.get_main_loop() as SceneTree).root.get_node("Controls")
 if controls.controller_active and controls.binding_events("homestead","controller").is_empty():return controls.action_label("crafting")+" → "+controls.action_label("potion")
 return controls.action_label("homestead")

func valid() -> bool:
 if not active or GameState.map_id!=map_id or GameState.ended or GameState.transitioning:return false
 if source==null:return true
 var node: Node2D=source.get_ref()
 return is_instance_valid(node) and node.is_visible_in_tree() and not node.is_queued_for_deletion() and world.player.position.distance_to(node.position)<=68

func rebuild():
 for child in box.get_children():box.remove_child(child);child.queue_free()
 buttons.clear();tool_grid=null;tool_info=null;role_card=null
 var node: Node2D=source.get_ref() if source!=null else null
 var role: String=node.obj.role if node!=null else "tools"
 theme_id=role;Identity.style_panel(panel,role)
 var title:=Style.make_label(station_name(role) if role!="tools" else tr("Tuinhak · kies je werk"),26,Color("f0d39b"));box.add_child(title)
 title.modulate=Identity.accent(role).lightened(.15)
 if role!="tools":
  role_card=load("res://scripts/ui/workplace_card.gd").new();role_card.role=role;role_card.unit=node.obj.get("unit","") if node!=null else "";box.add_child(role_card)
 if role=="tools":
  message(tr("Kies je werk en houd %s vast terwijl je langs een rij loopt; herstellen werkt per druk.") % Controls.action_label("interact"))
  tool_grid=GridContainer.new();tool_grid.columns=2;tool_grid.add_theme_constant_override("h_separation",8);tool_grid.add_theme_constant_override("v_separation",6);box.add_child(tool_grid)
  for mode in ["soil","channel","grape","flower","fertilize","harvest","fill",""]:
   var item: String={"grape":"hs_seed","flower":"hs_flower_seed","fertilize":"hs_fertilizer"}.get(mode,"")
   var text: String=tr("%s · bij je: %d") % [mode_name(mode),GameState.count(item)] if item!="" else mode_name(mode)
   var b: Button=button(("✓ " if Farm.mode==mode else "")+text,choose.bind(mode),mode!="" and GameState.count("hs_hoe")==0,tool_grid)
   b.focus_entered.connect(show_tool_info.bind(mode))
  tool_info=Style.make_label("",17,Color("c9dfcb"));tool_info.autowrap_mode=TextServer.AUTOWRAP_WORD_SMART;tool_info.custom_minimum_size=Vector2(620,44);box.add_child(tool_info)


 elif role in ["guide","supplies"]:
  message(tr("Dit huis en de tuin zijn van jou. Buiten: twee wijnvaten, mesthoop achter het dak en een bijenkast. Haal je gratis hak en zaden. Leid met kanaaltjes water uit de dorpsbeek naar de grond; droge gewassen wachten zonder te verdorren. Druiven groeien in 90 s, bloemen in 60 s actieve speeltijd. Menu's pauzeren de tijd."))
  button(tr("Neem hak en zaden · eenmalig gratis"),supply,GameState.flag("hs_supplies"))
  button(tr("Tuinstanden openen"),tools)
  button(tr("Oogst alle rijpe gewassen in je tuin"),harvest)
  message(Feedback.guide_text())
  button(tr("Tuinhulp stoppen") if GameState.flag("hs_garden_help") else tr("Tuinhulp starten · vrijwillig"),toggle_help)
 elif role=="bed":
  message(tr("Een rustige eigen woning. Rusten vult hartjes en stamina aan en slaat hier op. Het blauwe punt voor je huis ontdekt een snelreisbestemming op de kaart."))
  button(tr("Rusten en opslaan"),rest)
 elif role=="wild_grape":
  message(tr("Verzamel drie bosdruiven. Eet ze voor één hartje, maak pitten via Beroepen of vul je wijnvat. De struik herstelt na 120 s actieve speeltijd."))
  button(tr("Pluk drie druiven"),grapes,GameState.play_time<Farm.state().wild_due or GameState.room("hs_grape")<3)
 elif role=="hive":
  message(tr("Bloemen in bereik: %d / 3 nodig. Bloeiende planten binnen vijf tegels geven bijen voedsel. Zonder bloemen pauzeert de productie. Iedere 120 s actieve speeltijd één honing; de kast bewaart maximaal acht.") % Farm.flowers())
  message(tr("Honing klaar: %d · voortgang %.0f / 120 s") % [Farm.state().honey,Farm.state().honey_time])
  button(tr("Honing uit de kast halen"),collect.bind("hive"),Farm.state().honey==0 or GameState.room("hs_honey")<Farm.state().honey)
 else:
  var id: String="compost" if role=="compost" else node.obj.unit
  var recipe: Dictionary=Farm.JOBS[id]
  message(tr("Composteren · twee dierenpoep worden drie meststof in 30 s.") if role=="compost" else tr("Wijn maken · drie druiven worden één fles in 90 s."))
  message(tr("Beschikbaar: %d · nodig per portie: %d · maximaal twintig porties tegelijk") % [load("res://scripts/core/stockroom.gd").available(recipe.input),recipe.cost])
  if load("res://scripts/core/stockroom.gd").nearby_kind()!="":message(tr("Ingrediënten uit de bereikbare huisvoorraad tellen mee."))
  if Farm.state().jobs.has(id):
   var job: Dictionary=Farm.state().jobs[id]
   message(tr("Nog %.0f s actieve speeltijd · resultaat: %d") % [maxf(0,recipe.seconds-job.time),job.batches*recipe.yield])
   button(tr("Meststof uitscheppen") if role=="compost" else tr("Wijn bottelen"),collect.bind(id),job.time<recipe.seconds or GameState.room(recipe.output)<job.batches*recipe.yield)
  else:
   var count: int=mini(20,load("res://scripts/core/stockroom.gd").available(recipe.input)/recipe.cost)
   button(tr("Meng één portie compost") if role=="compost" else tr("Vul vat voor één fles"),start.bind(id,1),count<1)
   if count>1:button((tr("Meng %d porties compost") if role=="compost" else tr("Vul vat voor %d flessen")) % count,start.bind(id,count))
 if GameState.map_id=="player_home" and role in ["bed","guide","supplies"]:button(tr("Je huis inrichten"),decorate)
 var ending: Node=null
 if role in ["tools","guide","supplies"]:
  ending=GridContainer.new();ending.columns=2;ending.add_theme_constant_override("h_separation",8);ending.add_theme_constant_override("v_separation",6);box.add_child(ending)
 if role=="tools":
  button(tr("Wateroverzicht: aan") if Farm.show_water else tr("Wateroverzicht: uit"),toggle_water,false,ending)
  button(tr("Tuinhulp stoppen") if GameState.flag("hs_garden_help") else tr("Tuinhulp starten · vrijwillig"),toggle_help,false,ending)
 if role in ["tools","guide","supplies"]:button(tr("Zaden en boomgaard"),seeds,false,ending)
 if GameState.map_id=="village" and role in ["tools","guide","supplies"]:button(tr("Erf inrichten"),yard,false,ending)
 button(tr("Sluiten"),close,false,ending)
 var focus: Array[Control]=[]
 for b in buttons:
  if not b.disabled:focus.append(b)
 Style.link_vertical(focus)
 if tool_grid!=null:link_tools(focus)
 device_changed(Controls.controller_active);layout()
 var selected: Button=null
 if tool_grid!=null:
  var index: int=["soil","channel","grape","flower","fertilize","harvest","fill",""].find(Farm.mode)
  if Farm.mode=="" and GameState.count("hs_hoe")>0:index=0
  if index>=0 and not buttons[index].disabled:selected=buttons[index]
 (selected if selected!=null else focus[0]).grab_focus()

func choose(value: String):
 if not valid():return
 Farm.mode=value;close()
 for n in get_tree().get_nodes_in_group("homesteads"):
  n.cooldown=.3;n.waiting_release=Input.is_action_pressed("interact");n.clear_stroke()

func tools():
 if not valid():return
 source=null;rebuild()

func supply():
 if not valid():return
 Farm.starter();rebuild()

func harvest():
 if not valid():return
 Farm.harvest_all();rebuild()

func rest():
 if not valid():return
 GameState.full_rest();GameState.save_requested.emit();close()

func grapes():
 if not valid():return
 Farm.wild_grapes();rebuild()

func layout():
 var size:=get_viewport().get_visible_rect().size;panel.size=panel.get_combined_minimum_size()
 var factor:=minf(1,minf((size.x-32)/panel.size.x,(size.y-32)/panel.size.y));panel.scale=Vector2.ONE*factor;panel.position=(size-panel.size*factor)*.5

func _process(_delta: float):
 if active:
  if not valid():close();return
  layout()

func _unhandled_input(event: InputEvent):
 if not active or Engine.get_process_frames()<=opened_frame or not Controls.allows_event(event):return
 if event.is_action_pressed("ui_cancel") or event.is_action_pressed("homestead"):close();get_viewport().set_input_as_handled()
 elif Style.activate_focused(root,event):get_viewport().set_input_as_handled()

func toggle_water():
 if not valid():return
 Farm.show_water=not Farm.show_water;rebuild()

func toggle_help():
 if not valid():return
 GameState.set_flag("hs_garden_help",not GameState.flag("hs_garden_help"));GameState.save_requested.emit();rebuild()

func link_tools(focus: Array[Control]):
 var grid_buttons: Array=tool_grid.get_children()
 for i in grid_buttons.size():
  var b: Button=grid_buttons[i]
  if b.disabled:continue
  var side: Button=grid_buttons[i+1 if i%2==0 else i-1]
  b.focus_neighbor_left=b.get_path_to(side if not side.disabled else b);b.focus_neighbor_right=b.focus_neighbor_left
  for direction in [-1,1]:
   var index: int=i+int(direction)*2
   while index>=0 and index<grid_buttons.size() and grid_buttons[index].disabled:index+=direction*2
   var other: Control=grid_buttons[index] if index>=0 and index<grid_buttons.size() else focus[focus.size()-1] if direction<0 else buttons[8]
   if direction<0:b.focus_neighbor_top=b.get_path_to(other)
   else:b.focus_neighbor_bottom=b.get_path_to(other)

func decorate():
 if not valid() or GameState.map_id!="player_home":return
 close()
 var ui: CanvasLayer=load("res://scripts/ui/house_ui.gd").new();ui.world=world;world.add_child(ui);ui.open()

func yard():
 if not valid() or GameState.map_id!="village":return
 close()
 var ui: CanvasLayer=load("res://scripts/ui/yard_ui.gd").new();ui.world=world;world.add_child(ui);ui.open()

func seeds():
 if not valid():return
 close()
 var ui: CanvasLayer=load("res://scripts/ui/orchard_ui.gd").new();ui.world=world;world.add_child(ui);ui.open()

